{
  "title": "Sun, stars and a hidden courtyard",
  "summary": "A day that starts with Inti (the sun (Quechua)) on ancient stone, then slips into a neighbourhood the crew has not yet met, with a planetarium after dark.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Kept as the must-do anchor, so the crew still feels the old Inca pulse before the surprise begins.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "The unexpected turn: a slow wander through San Blas, all workshops, blue doors and quiet corners no one asked for but everyone will photograph."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at a proper vegetarian table, easy on the wallet and kind to every belly in the crew."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Kept as the after-dark surprise: Cusco’s sky told through Inca eyes, a fitting close for a day that began with Inti."
    }
  ]
}
